const services = [
  { name: 'Ticket Service', node: 'Ticket Service' },
  { name: 'Auth Service', node: 'Auth Service' },
  { name: 'Organisation Service', node: 'Organisation Service' },
  { name: 'Rules Service', node: 'Rules Service' },
  { name: 'Decision Service', node: 'Decision Service' },
  { name: 'Notification Service', node: 'Notification Service' },
  { name: 'Analytics Service', node: 'Analytics Service' },
  { name: 'AI Service (Python)', node: 'AI Service' },
  { name: 'API Gateway', node: 'API Gateway' }
];

const now = new Date().toLocaleString('fr-FR');
const results = [];
let downCount = 0;

for (const svc of services) {
  let isUp = false;
  try {
    const data = $(svc.node).first();
    if (data && data.json) {
      if (data.json.error) {
        isUp = String(data.json.error).includes('Invalid JSON');
      } else {
        isUp = true;
      }
    }
  } catch (e) {
    isUp = false;
  }
  results.push({
    name: svc.name,
    status: isUp ? '\u2705 UP' : '\u274c DOWN',
    color: isUp ? '#2E7D32' : '#C62828'
  });
  if (!isUp) downCount++;
}

if (downCount === 0) {
  return [];
}

const rows = results.map(r =>
  '<tr><td style="padding:10px;border-bottom:1px solid #eee;">' + r.name + '</td><td style="padding:10px;border-bottom:1px solid #eee;color:' + r.color + ';font-weight:700;">' + r.status + '</td></tr>'
).join('');

const html = '<div style="font-family:Segoe UI,Arial,sans-serif;max-width:600px;margin:0 auto;"><div style="background:linear-gradient(135deg,#E65100,#F57C00);color:white;padding:25px;border-radius:12px 12px 0 0;text-align:center;"><h1 style="margin:0;">\ud83c\udfe5 Alerte Infrastructure AutoAssist</h1><p style="margin:5px 0 0;opacity:0.9;">' + downCount + ' service(s) indisponible(s) \u2014 ' + now + '</p></div><div style="background:white;padding:25px;border:1px solid #e0e0e0;"><table style="width:100%;border-collapse:collapse;"><tr style="background:#FFF3E0;"><th style="padding:10px;text-align:left;">Service</th><th style="padding:10px;text-align:left;">\u00c9tat</th></tr>' + rows + '</table></div><div style="background:#f8f9fa;padding:15px;border-radius:0 0 12px 12px;text-align:center;color:#888;font-size:12px;"><p>\u00a9 2026 AutoAssist \u2014 Monitoring automatique n8n</p></div></div>';

return [{ json: { html, subject: '\ud83c\udfe5 ALERTE \u2014 ' + downCount + ' service(s) DOWN \u2014 AutoAssist', downCount } }];
